// Changes: Behaviour of the toast stack – toasts stack, errors persist, announcement text.

import { describe, expect, it } from 'vitest'
import { addToast, dismissToast, toastAnnouncement, type ToastItem } from './toastStack'

const make = (id: number, tone: ToastItem['tone'] = 'ok'): ToastItem => ({ id, title: `T${id}`, tone, duration: tone === 'bad' ? null : 5000 })

describe('toast stack', () => {
  it('stacks new toasts after the existing ones instead of replacing them', () => {
    const stack = addToast(addToast([], { title: 'Uložené', tone: 'ok' }, 1), { title: 'Importované', tone: 'info' }, 2)
    expect(stack.map((t) => t.title)).toEqual(['Uložené', 'Importované'])
  })

  it('keeps error toasts until dismissed and times out the others', () => {
    const stack = addToast(addToast([], { title: 'Zlyhalo', tone: 'bad', duration: 3000 }, 1), { title: 'OK', tone: 'ok' }, 2)
    expect(stack[0].duration).toBeNull()
    expect(stack[1].duration).toBe(5000)
  })

  it('defaults to the info tone', () => {
    expect(addToast([], { title: 'Ahoj' }, 1)[0].tone).toBe('info')
  })

  it('drops the oldest timed toast when the stack is full, never an error', () => {
    let stack: ToastItem[] = [make(1, 'bad'), make(2), make(3), make(4)]
    stack = addToast(stack, { title: 'T5' }, 5, 4)
    expect(stack.map((t) => t.id)).toEqual([1, 3, 4, 5])
  })

  it('drops the oldest error when the full stack holds only errors', () => {
    const stack = addToast([make(1, 'bad'), make(2, 'bad')], { title: 'T3', tone: 'bad' }, 3, 2)
    expect(stack.map((t) => t.id)).toEqual([2, 3])
  })

  it('dismisses a toast by id', () => {
    expect(dismissToast([make(1), make(2)], 1).map((t) => t.id)).toEqual([2])
  })

  it('announces only the visible text, mentioning available actions', () => {
    expect(toastAnnouncement({ id: 1, title: 'Import zlyhal', description: 'Zlý súbor', tone: 'bad', duration: null })).toBe(
      'Chyba: Import zlyhal. Zlý súbor',
    )
    expect(toastAnnouncement({ id: 2, title: 'Projekt zmazaný', tone: 'info', duration: 5000, actionLabel: 'Späť', onAction: () => {} })).toBe(
      'Projekt zmazaný. Akcie sú dostupné.',
    )
  })
})
